// src/film.ts
var LINES = lines_bars_default;
var SCENES = [];
var FALLBACK = {};
var addScene = (s) => {
  SCENES.push(s);
  SCENES.sort((p, q) => p.a - q.a);
};
var renderFilm = (t, hud2) => {
  hud2.innerHTML = "";
  let i = SCENES.findIndex((s) => t >= s.a && t < s.z);
  if (i < 0) i = t < SCENES[0].a ? 0 : SCENES.length - 1;
  const cur = SCENES[i], tr = cur.in && i > 0 && t >= cur.in.a && t < cur.in.z ? cur.in : null;
  const safe = (sc, tt) => {
    try {
      return sc.draw(tt);
    } catch (e) {
      console.error("DRAW-FAIL", sc.id, tt.toFixed(2), e?.message || e);
      FALLBACK.st ??= new Stage("fallback");
      return { st: FALLBACK.st, grade: { vig: 0 } };
    }
  };
  const fc = safe(cur, t);
  if (tr) {
    const prev = SCENES[i - 1], fp = safe(prev, t);
    renderStage(fp.st, 0, fp.bloom ?? 1);
    renderStage(fc.st, 1, fc.bloom ?? 1);
    const k = (tr.ease ?? ((u) => u))(clamp01((t - tr.a) / (tr.z - tr.a)));
    const x = { mode: tr.mode, k, dir: tr.dir, pt: tr.pt, soft: tr.soft, band: tr.band };
    composite(x, fc.grade ?? {}, t, fp.bloom ?? 1, fc.bloom ?? 1);
  } else if (fc.under) {
    renderStage(fc.under, 0, 1);
    renderStage(fc.st, 1, fc.bloom ?? 1);
    composite({ mode: 13, k: 1, blurA: fc.blurUnder ?? 0 }, fc.grade ?? {}, t, 1, fc.bloom ?? 1);
  } else {
    renderStage(fc.st, 0, fc.bloom ?? 1);
    composite({ mode: 0, k: 0 }, fc.grade ?? {}, t, fc.bloom ?? 1);
  }
  if (!fc.hideSubs) subtitles(hud2, LINES, t);
  drawFurniture(hud2, t, { hideAll: fc.hideFurniture });
  fc.hud?.(hud2);
};

